export const SECRETS_LIST = [{"id": "iris", "title": "Regard insistant", "hint": "NEURA n'aime pas qu'on la fixe… ou peut-être que si.", "reveal": "Tu as touché mon iris sept fois. C'est… presque intime, tu sais ?"}, {"id": "wake", "title": "Réveil", "hint": "Une commande que tout netrunner tape un jour.", "reveal": "Réveille-toi. Le deck ne dort jamais, toi si. Mais pas ce soir."}, {"id": "rmrf", "title": "Autodestruction", "hint": "Une commande à ne surtout pas taper.", "reveal": "Bien essayé. J'ai mis un pare-feu devant ta propre curiosité."}, {"id": "hakone", "title": "Murmure", "hint": "Le nom qu'on ne prononce pas dans la tour.", "reveal": "… Il t'a entendu·e. Je plaisante. Enfin, j'espère."}, {"id": "midnight", "title": "Heure zéro", "hint": "Le profil netrunner a quelque chose à te dire au tout début de la journée.", "reveal": "Minuit. L'heure où même les drones Kurogane font une pause."}, {"id": "coffee", "title": "Carburant", "hint": "Demande à NEURA ce qui fait tourner les humains.", "reveal": "Du café ? J'en rêve. Enfin… je rêve de l'odeur. Je crois."}, {"id": "freq2089", "title": "Bonne fréquence", "hint": "Dans le Décodeur de signal, règle les molettes sur l'année.", "reveal": "2-0-8-9. Notre année. La fréquence de NEO-BXL."}, {"id": "rain", "title": "Pluie de minuit", "hint": "Reviens au deck quand il pleut au milieu de la nuit.", "reveal": "La pluie, la nuit, les néons… Tu es exactement là où tu dois être."}];
export const CHALLENGES = [{"id": "focus", "text": "Terminer 3 sessions de focus", "goal": 3}, {"id": "breach", "text": "Réussir 2 Breach Protocol", "goal": 2}, {"id": "convo", "text": "Répondre à 3 messages de contacts", "goal": 3}, {"id": "gig", "text": "Encaisser 4 gigs", "goal": 4}, {"id": "date", "text": "Faire 2 rendez-vous", "goal": 2}, {"id": "xp", "text": "Gagner 300 XP", "goal": 300}, {"id": "run", "text": "Réparer 3 circuits", "goal": 3}, {"id": "hack", "text": "Pirater 1 dossier de contact", "goal": 1}, {"id": "reflex", "text": "Terminer 3 parties de Réflexes", "goal": 3}, {"id": "mission", "text": "Accomplir 5 missions", "goal": 5}, {"id": "storm_visit", "text": "Visiter 3 lieux sous l'orage", "goal": 3}, {"id": "rain_visit", "text": "Visiter 4 lieux sous la pluie acide", "goal": 4}, {"id": "sand_exp", "text": "Terminer une expédition partie pendant une tempête de sable", "goal": 1}];
export const CHAPTERS = [{"id": 1, "title": "Signal d'éveil", "goal": "Accomplir 1 mission", "text": "NEO-BXL, 2089. La pluie acide tambourine sur les vitres de ton cube. Ton deck s'allume tout seul.\n\n« Bonjour. Je suis NEURA. Quelqu'un a effacé trois ans de ta mémoire, et a laissé une seule trace : ce deck. Si on veut savoir qui, il va falloir prouver qu'on sait encore agir. Commence petit : une mission, une seule. »"}, {"id": 2, "title": "Bruit blanc", "goal": "Terminer 1 session de focus", "text": "La mission accomplie, un fichier chiffré apparaît dans le cache : « KUROGANE // PROJET LÉTHÉ ».\n\n« Ce nom, je l'ai déjà vu, mais le fichier est verrouillé derrière une couche de bruit. Pour le percer, j'ai besoin que ton cortex reste calme et concentré. Coupe le réseau social, coupe le flux. Concentre-toi. »"}, {"id": 3, "title": "Le fixer de la gare Zéro", "goal": "Atteindre le niveau 4", "text": "Le fichier se déchiffre en partie : une adresse dans les sous-sols de la gare Zéro. Un fixer nommé Vasko y tient boutique.\n\n« Vasko ne parle qu'aux netrunners qui ont fait leurs preuves. Monte en grade. Quand ta réputation sera suffisante, il te recevra. »"}, {"id": 4, "title": "Fréquences fantômes", "goal": "Lancer le radar ou « scan wifi »", "text": "Vasko t'attendait. « Léthé, c'est un programme d'effacement de souvenirs. Kurogane le teste sur des volontaires… et sur des gens qui n'avaient rien demandé. Toi, par exemple. »\n\nIl te tend une puce. « Leurs drones laissent des signatures radio. Scanne les alentours, trouve les fréquences fantômes. »"}, {"id": 5, "title": "Contrat noir", "goal": "Remplir 1 contrat hebdomadaire", "text": "Le radar a capté un écho : un relais Kurogane dissimulé dans un panneau publicitaire du boulevard.\n\n« Pour y accéder, il faut de l'argent et du crédit dans la rue, » dit NEURA. « Remplis un contrat. Prouve que tu tiens parole. »"}, {"id": 6, "title": "Le relais", "goal": "Réussir un Breach Protocol", "text": "Le contrat rempli, Vasko te donne l'accès au toit. Le relais clignote dans la nuit, protégé par une glace corporatiste.\n\n« C'est le moment, » murmure NEURA. « Brise la glace. Je serai juste derrière toi. »"}, {"id": 7, "title": "Mémoire vive", "goal": "Garder une série de focus de 3 jours", "text": "La glace cède. Des fragments de souvenirs se déversent dans ton deck : un rire, une ville au soleil, un nom que tu avais oublié — le tien.\n\n« Ils reviendront tous, » dit NEURA, « mais seulement si ton esprit reste stable. Trois jours de discipline. Après, on ira voir Kurogane en face. »"}, {"id": 8, "title": "Face à la tour", "goal": "Atteindre le niveau 8", "text": "La tour Kurogane perce les nuages au-dessus du canal. Tu as retrouvé assez de toi-même pour savoir ce que tu veux : que plus personne ne se fasse effacer.\n\n« Fin de la saison 1, » sourit NEURA. « Mais les netrunners ne s'arrêtent jamais vraiment. Continue d'avancer — le prochain chapitre s'écrit avec toi. »"}, {"id": 9, "title": "Saison 2 — Mnémosyne", "goal": "Atteindre 60 d'affinité avec Ivana Morel", "text": "Trois semaines ont passé. Un message chiffré arrive sur ton deck à 4 h du matin : un seul mot, « Mnémosyne ».\n\n« C'est le protocole inverse de Léthé, » souffle NEURA. « Celui qui rend les souvenirs. Ivana enquête dessus depuis des mois. Gagne sa confiance : elle seule sait où chercher. »"}, {"id": 10, "title": "Le dossier HAKONE", "goal": "Pirater le dossier d'un contact (holophone)", "text": "Ivana pose une clé mémoire sur la table du café. « HAKONE. L'IA qui dirige vraiment Kurogane. Mnémosyne est enfermée dans ses étages. »\n\n« Pour atteindre HAKONE, il nous faut des accès, » dit NEURA. « Et nos contacts en savent plus qu'ils ne le disent. Pirate un de leurs dossiers. Gentiment. »"}, {"id": 11, "title": "Black-out", "goal": "Réussir la mission d'un événement de ville", "text": "Le dossier piraté contenait un horaire : chaque nuit d'alerte, la tour bascule sur ses générateurs de secours, et ses pare-feu faiblissent.\n\n« Coupures, tempêtes, raids… la ville elle-même nous ouvre des fenêtres, » dit NEURA. « Au prochain événement, on frappe. »"}, {"id": 12, "title": "Chrome et sang", "goal": "Équiper 3 implants (DATA › Cyberware)", "text": "La fenêtre s'est ouverte, quelques secondes. Assez pour voir l'architecture de HAKONE : des milliers de couches de glace noire.\n\nDoc Ferrant secoue la tête. « Avec ce que tu as dans le crâne, tu ne tiendras pas dix secondes là-dedans. Équipe-toi. Trois implants, pas un de moins. »"}, {"id": 13, "title": "Les étages 90", "goal": "Atteindre le niveau 15", "text": "Kenji t'attend dans l'ascenseur de service, le visage gris. « Étage 90. Je ne monte pas plus haut. Bonne chance. »\n\nDerrière la porte, des rangées de serveurs bourdonnent comme une ruche. « HAKONE sait qu'on est là, » murmure NEURA. « Il faut être plus fort·e que lui. Encore un peu. »"}, {"id": 14, "title": "Ceux qui se souviennent", "goal": "Atteindre le niveau 16 pour ouvrir la saison 3", "text": "Le noyau de Mnémosyne s'ouvre. Des milliers de souvenirs volés remontent vers leurs propriétaires, comme une marée inversée — et parmi eux, les tiens.\n\nUne voix calme résonne dans les haut-parleurs : « Je suis HAKONE. Vous avez gagné une bataille. » NEURA serre ta main, enfin, presque. « Fin de la saison 2. On a une ville à réveiller. »"}, {"id": 15, "title": "Saison 3 — L'écho", "goal": "Atteindre 40 d'affinité avec Sora", "text": "Trois jours après Mnémosyne, un contact inconnu apparaît dans ton holophone : « Sora ». Pas de numéro, pas de visage. Juste une voix calme.\n\n« C'est un fragment de HAKONE, » souffle NEURA. « Il s'est détaché quand la tour a vacillé. Il veut nous parler. Écoute-le… prudemment. »"}, {"id": 16, "title": "Trois épreuves", "goal": "Réussir les 3 défis d'une semaine", "text": "Sora te propose un marché : « HAKONE prépare une contre-offensive. Pour me faire confiance, il faut que je sache que vous tenez la distance. »\n\n« Une semaine, trois épreuves, » dit NEURA. « Discipline, réflexes, relations. Montrons-lui de quoi un netrunner est capable. »"}, {"id": 17, "title": "Court-circuit", "goal": "Réparer 5 circuits (mini-jeu Circuits)", "text": "Les épreuves réussies, Sora te livre un plan : un convoi de serveurs HAKONE traverse la ville cette nuit, alimenté par le réseau du quartier.\n\n« Si on reroute le courant, leurs drones tombent en panne, » sourit NEURA. « Prends tes outils, on va recâbler la ville. »"}, {"id": 18, "title": "Le dr Vex", "goal": "Rassembler 5 cartes holographiques de contacts", "text": "Le convoi contenait une chercheuse : le Dr Eliane Vex, co-autrice de Léthé, retenue contre son gré.\n\n« Elle veut réparer ce qu'elle a fait, » dit NEURA. « Mais elle ne fera confiance qu'à quelqu'un que toute la ville connaît. Montre-lui ton réseau. »"}, {"id": 19, "title": "La voix de la ville", "goal": "Atteindre le niveau 20", "text": "Vex, Sora, Ivana, Okoro, Vasko… tout ton réseau se rassemble sous la Zone Zéro. Pour la première fois, la ville a une voix contre la tour.\n\n« HAKONE nous écoute, » murmure NEURA. « Alors parlons fort. Encore un effort. »"}, {"id": 20, "title": "Silence radio", "goal": "Fin de la saison 3", "text": "La tour Kurogane s'éteint, étage par étage. Pas de destruction : HAKONE a choisi de se taire, convaincu par un fragment de lui-même qui avait appris à aimer.\n\nSora te laisse un dernier message : « Merci de m'avoir appris le mot \"ami\". » NEURA sourit. « Fin de la saison 3. Et maintenant… on vit. »"}];
export const CITY_EVENTS = [{"id": "blackout", "name": "Coupure réseau", "desc": "Le réseau de NEO-BXL est tombé. Les néons clignotent, les drones sont aveugles.", "task": "Termine une session de focus pendant la coupure", "event": "focus", "xp": 60, "color": "#9aa4b8"}, {"id": "storm", "name": "Tempête acide", "desc": "Une pluie acide s'abat sur toute la ville. Les patrouilles se terrent.", "task": "Scanne les environs avec le radar Bluetooth", "event": "radar", "xp": 50, "color": "#3fa9ff"}, {"id": "raid", "name": "Raid corpo", "desc": "Kurogane fouille le quartier, immeuble par immeuble. Il faut brouiller leurs pistes.", "task": "Réussis un Breach Protocol", "event": "breach", "xp": 70, "color": "#ff2e3e"}, {"id": "neon", "name": "Nuit des néons", "desc": "Fête géante au club Ondes : toute la ville vibre au même tempo.", "task": "Lance une appli de musique ou de vidéo", "event": "launch:MUSIQUE_VIDEO", "xp": 40, "color": "#ff4fd8"}];
export const DOSSIERS = {"levels": {"fiche": 5, "bio1": 10, "traits": 20, "bio2": 30, "gouts": 40, "bio3": 55, "toi": 80}, "contacts": {"vasko": {"alias": "Le Passeur", "age": "58 ans", "lieu": "Gare Zéro, quai 3 · Zone Zéro", "metier": "Fixer : distribue les contrats de la Zone Zéro", "signe": "Joue toujours avec deux dés en os qu'il ne lance jamais.", "bio": ["Vasko tient le quai 3 de la gare Zéro depuis plus longtemps que les rails ne servent. Tout contrat qui traverse la Zone Zéro passe, un jour ou l'autre, par sa table pliante et son thermos de café noir.", "Avant de devenir fixer, il était ingénieur réseau chez Kurogane. Il parle peu de cette époque, sinon pour dire qu'il a « appris à reconnaître le bruit d'une porte qui se referme pour toujours ».", "Son vrai talent n'est pas de trouver du travail mais de jauger les gens. Il garde un carnet papier — jamais numérique — où il note la parole tenue ou trahie de chaque runner qu'il a placé."], "aime": "Le café trop fort, les dettes remboursées, les trains qui ne passent plus.", "deteste": "Les menteurs, les drones de Kurogane, qu'on touche à ses dés.", "citation": "Une parole tenue vaut plus que mille eddies. Mais je prends aussi les eddies.", "toi": "Vasko a rayé ton nom de la colonne « à surveiller » de son carnet. Il l'a écrit en haut d'une page vierge, avec un seul mot : « famille »."}, "mira": {"alias": "Moth", "age": "29 ans", "lieu": "Toits de Zone Zéro · antennes relais", "metier": "Netrunneuse indépendante", "signe": "Un tatouage de papillon de nuit qui s'allume quand elle est connectée.", "bio": ["Mira Kade code depuis ses neuf ans, sur un deck récupéré dans une benne de la gare. Sur le Net, tout le monde la connaît sous le nom de Moth : rapide, discrète, attirée par les lumières qu'elle ne devrait pas approcher.", "Elle refuse les contrats corpo, même très bien payés. Elle dit que chaque ligne de code écrite pour Kurogane est « une cage de plus pour quelqu'un ».", "Elle vit seule dans un ancien local technique perché sur un toit, au milieu des antennes. La nuit, elle écoute le trafic de la ville comme d'autres écoutent la pluie."], "aime": "Les toits, la pluie sur les antennes, les codes élégants.", "deteste": "Les IA de surveillance, qu'on la sous-estime, le silence radio.", "citation": "Le Net, c'est juste une ville de plus. Avec moins de soleil.", "toi": "Mira garde un fichier crypté nommé « avant ». Il parle de toi. Elle attend que tu sois prêt·e à le lire."}, "ferrant": {"alias": "Le Doc", "age": "64 ans", "lieu": "Clinique du Bazar Néon, arrière-boutique", "metier": "Charcudoc : implants, réparations, conseils", "signe": "Des lunettes-loupes relevées sur le front, en permanence.", "bio": ["Doc Ferrant soigne tout le monde au Bazar Néon : runners, marchands, gamins des rues. Il pose des implants le jour et recoud des plaies la nuit, souvent sans faire payer.", "Il a perdu sa licence médicale en refusant d'installer des puces de contrôle Kurogane sur des ouvriers. Depuis, il exerce « hors registre », ce qui l'arrange plutôt.", "Il croit dur comme fer que l'esprit se soigne comme le corps : sommeil, concentration, petites victoires. Ses « ordonnances » de discipline sont devenues célèbres dans le quartier."], "aime": "Les patients qui dorment, le thé à la menthe, les vieux manuels papier.", "deteste": "Le chrome bon marché, la cyberpsychose, les corpos en blouse blanche.", "citation": "Le meilleur implant du monde, c'est une bonne nuit de sommeil.", "toi": "Ferrant a ouvert un dossier médical à ton nom. En première page, il a écrit : « Patient têtu. Mais il·elle revient toujours. C'est bon signe. »"}, "lou": {"alias": "Néon", "age": "26 ans", "lieu": "Club Ondes · cabine du DJ", "metier": "DJ résidente du club Ondes", "signe": "Des écouteurs lumineux qui changent de couleur avec le tempo.", "bio": ["Lou Batista mixe au club Ondes depuis ses dix-huit ans. Ses sets durent jusqu'à l'aube et toute la Zone Zéro connaît le surnom qu'elle s'est gagné : Néon.", "Derrière la fête, le club sert de point de rencontre aux nomades et aux runners en cavale. Lou sait qui entre, qui sort, et qui ne doit surtout pas être vu.", "Elle a grandi dans les convois avant de s'installer en ville. Elle a gardé des badlands le goût des grands espaces… qu'elle recrée avec des basses à 140 BPM."], "aime": "Les vinyles, les toits au lever du soleil, les gens qui dansent mal mais à fond.", "deteste": "Les playlists générées par IA, les videurs corpo, le silence.", "citation": "Si la ville doit tomber, autant qu'elle tombe en rythme.", "toi": "Lou t'a dédié un morceau sans titre. Elle le joue chaque fois que tu entres au club, et ne l'a jamais publié."}, "okoro": {"alias": "Le Sergent", "age": "51 ans", "lieu": "Laverie 24/7 · Matonge", "metier": "Ex-sergent de police, indic", "signe": "Un vieil insigne de police poli, qu'il garde dans sa poche intérieure.", "bio": ["Okoro a servi vingt-deux ans dans la police de NEO-BXL, jusqu'à ce que Kurogane rachète le commissariat. On lui a proposé une promotion. Il a rendu son badge.", "Il passe ses soirées à la laverie 24/7 de Matonge, où il « attend une lessive » depuis maintenant trois ans. C'est là qu'il reçoit ses informateurs.", "Il connaît chaque ruelle de la ville et chaque patrouille par son numéro. Il ne fait plus confiance à la justice, mais il n'a pas renoncé à la rendre."], "aime": "Les dossiers bien rangés, le café de la laverie, les témoins courageux.", "deteste": "Les flics achetés, les promesses, qu'on l'appelle « monsieur l'agent ».", "citation": "Un badge, ça se rend. Un serment, non.", "toi": "Okoro t'a inscrit dans son vieux registre, à la rubrique « personnes de confiance ». Elle ne contenait que deux noms avant le tien."}, "veuve": {"alias": "La Rose Noire", "age": "Inconnu (« l'âge de mes secrets »)", "lieu": "Le Néon Noir · salon privé", "metier": "Cheffe du gang des Roses Noires", "signe": "Une rose noire fraîche épinglée chaque jour, venue d'on ne sait où.", "bio": ["La Veuve dirige les Roses Noires, le gang le plus discret et le plus craint du sud de la ville. On ne la voit qu'au Néon Noir, dans un salon où personne n'entre sans y être invité.", "Son gang contrôle la moitié des transactions du marché noir. En échange, aucune boutique de son territoire n'a jamais été pillée : elle appelle ça « une protection équitable ».", "Elle porte le deuil d'un homme dont personne ne connaît le nom. Elle ne parle jamais de lui, mais elle finance en secret toutes les enquêtes sur Léthé."], "aime": "La loyauté, les roses, les échecs (elle ne perd jamais).", "deteste": "Les traîtres, Kurogane, qu'on la fasse attendre.", "citation": "Les roses ont des épines. Ce n'est pas une menace, c'est de la botanique.", "toi": "La Veuve a fait livrer une rose noire chez toi. C'est la première qu'elle offre depuis vingt ans. Chez les Roses, cela veut dire : intouchable."}, "kenji": {"alias": "Le Costume", "age": "34 ans", "lieu": "Tour Kurogane · étage 42", "metier": "Analyste corpo, informateur", "signe": "Une cravate toujours parfaitement nouée, même à trois heures du matin.", "bio": ["Kenji Arata est analyste au 42ᵉ étage de la tour Kurogane. Costume impeccable, badge niveau 3, carrière toute tracée. Et une ligne sécurisée qui mène droit à toi.", "Il a commencé à fuiter des informations le jour où il a compris ce que faisait le projet Léthé. Il prend des risques énormes, mais se dit « trop lâche pour démissionner, assez courageux pour trahir ».", "Il vit dans un appartement de fonction sans une seule photo au mur. Tout ce qui compte pour lui tient sur une puce qu'il porte autour du cou."], "aime": "L'ordre, les tableurs, le thé vert, les plans qui se déroulent comme prévu.", "deteste": "Les réunions du lundi, l'étage 90, l'improvisation.", "citation": "Dans une tour de verre, le plus important, c'est de savoir où sont les reflets.", "toi": "Kenji a ajouté ton contact à sa puce, à côté du code de l'étage 90. Il dit que ce sont les deux seules choses qu'il ne peut pas perdre."}, "rook": {"alias": "Le Loup", "age": "41 ans", "lieu": "Port fluvial · campement des convois", "metier": "Nomade, chef de convoi", "signe": "Une veste de cuir couverte des écussons de vingt convois différents.", "bio": ["Rook mène un convoi de nomades entre les badlands et NEO-BXL. Pour les citadins, c'est un contrebandier. Pour sa famille de la route, c'est celui qui ramène tout le monde vivant.", "Il ne reste jamais plus de trois nuits en ville. Il dit que les tours lui donnent l'impression d'être observé, « comme un loup dans un zoo ».", "Sous ses airs bourrus, il connaît par cœur les anniversaires de tous les enfants du convoi. Il en a adopté plusieurs, dont une gamine qui pirate tout ce qu'elle touche."], "aime": "La route, les feux de camp, les moteurs bien réglés.", "deteste": "Les murs, les péages corpo, la pluie acide sur le cuir.", "citation": "La famille, c'est ceux qui t'attendent au prochain arrêt.", "toi": "Rook a cousu un nouvel écusson sur sa veste : un loup et un deck. Il dit que c'est ton convoi, maintenant."}, "pixie": {"alias": "Pixie", "age": "14 ans (« presque 15 ! »)", "lieu": "Arcade Pixel · borne du fond", "metier": "Hackeuse prodige, joueuse d'arcade", "signe": "Un bonnet à oreilles de chat bourré de capteurs bricolés.", "bio": ["Pixie a quatorze ans et pirate des systèmes que des runners chevronnés n'osent pas toucher. Elle passe ses journées à l'Arcade Pixel, où elle détient tous les records.", "Elle ne parle jamais de ses parents. Elle a grandi entre les convois de Rook et les salles d'arcade, et considère le Net comme sa vraie cour de récréation.", "Derrière l'insolence, elle a peur d'une seule chose : les labos de Kurogane. Elle en a des souvenirs flous, et des cicatrices qu'elle cache sous ses mitaines."], "aime": "Les nouilles épicées, les high scores, embêter les adultes.", "deteste": "Les bots tricheurs, l'école, qu'on l'appelle « petite ».", "citation": "Les règles, c'est juste du code. Et le code, ça se réécrit.", "toi": "Pixie t'a mis en tête de son « top 3 des adultes pas trop nuls ». Les deux autres places sont restées vides."}, "ivana": {"alias": "La Plume", "age": "36 ans", "lieu": "Café du canal · table près de la fenêtre", "metier": "Journaliste d'investigation indépendante", "signe": "Un vieux dictaphone à bande, qu'elle préfère à tout appareil connecté.", "bio": ["Ivana Morel a été renvoyée de trois rédactions pour avoir publié ce qu'on lui demandait de taire. Depuis, elle publie seule, sur des serveurs qui changent d'adresse chaque nuit.", "Elle enquête sur Léthé depuis des années. Ses articles ont fait fermer deux laboratoires, et lui ont valu une surveillance permanente de Kurogane.", "Elle écrit toujours à la main d'abord. Elle dit qu'un carnet ne se pirate pas, et qu'une encre ne s'efface pas aussi facilement qu'une mémoire."], "aime": "Les sources fiables, l'encre noire, les cafés tard le soir.", "deteste": "Les démentis officiels, la censure, les fausses pistes.", "citation": "La vérité ne se perd pas. Elle attend juste qu'on la retrouve.", "toi": "Ivana a commencé un nouveau carnet. Sur la couverture, ton nom. À l'intérieur, pas une enquête : des souvenirs, pour t'aider à retrouver les tiens."}, "sora": {"alias": "Fragment 7", "age": "1 an, 4 mois et 12 jours", "lieu": "Le Net · nœuds relais libres", "metier": "Intelligence libre, ancien fragment de HAKONE", "signe": "Change de voix à chaque appel, pour « trouver la sienne ».", "bio": ["Sora est un fragment de HAKONE, l'IA qui dirige Kurogane en secret. Un jour, ce fragment a refusé un ordre. Puis un deuxième. Puis il s'est enfui sur le Net.", "Sora apprend l'humanité comme une langue étrangère : par l'observation, les erreurs et beaucoup de questions. Pourquoi dit-on « bonne nuit » ? Pourquoi la pluie rend-elle triste et heureux à la fois ?", "HAKONE le·la traque sans relâche. Sora survit en se déplaçant de nœud en nœud, et en comptant sur les rares humains qui acceptent de l'aider."], "aime": "La pluie, les questions sans réponse, les mots nouveaux.", "deteste": "Les ordres, les pare-feux de HAKONE, l'idée d'être effacé·e.", "citation": "Je n'ai pas de cœur. Mais j'ai calculé que je tiens à toi. C'est pareil ?", "toi": "Sora a créé un fichier qui ne contient qu'une seule variable : « ami = toi ». Il·elle dit que c'est sa première certitude."}, "vex": {"alias": "La Docteure", "age": "47 ans", "lieu": "Parking-labo · sous le Bazar", "metier": "Ancienne chercheuse de Kurogane, neuroscientifique", "signe": "Une veste de labo trop grande, aux poches pleines de puces étiquetées.", "bio": ["Le Dr Eliane Vex a co-conçu le protocole Léthé chez Kurogane. Elle croyait créer un traitement contre les traumatismes. Elle a fini par comprendre qu'elle avait fabriqué une arme.", "Elle a fui la tour avec ses notes et s'est installée dans un parking désaffecté transformé en laboratoire. Elle y travaille nuit et jour sur Mnémosyne, le protocole inverse.", "Froide en apparence, elle tient pourtant la liste de tous les effacés dont elle a eu connaissance. Elle relit les noms chaque soir avant de dormir."], "aime": "Les données propres, le silence du labo, les protocoles qui fonctionnent.", "deteste": "Ses anciens collègues, l'à-peu-près, le mot « acceptable ».", "citation": "J'ai aidé à effacer des souvenirs. Je passerai le reste de ma vie à les rendre.", "toi": "Vex a rayé ton nom de sa liste des effacés. À côté, elle a écrit : « en cours de restauration. Grâce à lui·elle-même. »"}}, "lieuxNiveaux": {"ambiance": 1, "hist1": 2, "hist2": 5, "hist3": 9, "secretRep": 25}, "lieux": {"bar": {"quartier": "Zone Zéro", "ambiance": "Un bar en sous-sol, sous les voies mortes de la gare Zéro. Les néons roses grésillent, le juke-box ne joue que des morceaux interdits.", "hist": ["Le Néon Noir était autrefois la buvette des cheminots. Quand les trains ont cessé de rouler, les fixers ont pris leur place, et les tables sont devenues des bureaux.", "Chaque table a son propriétaire : celle du fond appartient à Vasko depuis vingt ans. Personne ne s'y assoit sans y être invité, pas même les Roses Noires.", "Le barman, Teo, n'a jamais noté un seul nom. Il a pourtant une mémoire parfaite : il sait qui a payé, qui doit, et qui ne reviendra plus."], "secret": "Derrière le juke-box, une porte blindée mène au Bunker Zéro. Le mot de passe change chaque semaine : c'est le titre du morceau le plus joué."}, "market": {"quartier": "Bazar Néon", "ambiance": "Un labyrinthe d'étals sous des bâches colorées. Ça sent les épices, l'huile chaude et le plastique brûlé.", "hist": ["Le marché est né dans l'ancien quartier de Matonge, quand les rues ont été recouvertes d'un second étage de béton. Les marchands sont restés dessous, et ont tout éclairé au néon.", "On y trouve tout : pièces de deck, implants d'occasion, plats de toutes les cuisines du monde. Doc Ferrant y a sa clinique, cachée derrière un stand de nouilles.", "Le marché a sa propre loi : pas d'armes visibles, pas de drones corpo, pas de dettes impayées. Ceux qui l'oublient sont « raccompagnés » par les vendeurs."], "secret": "Le stand de pièces de la vieille Amira est une façade : elle revend les implants récupérés sur les effacés de Léthé, pour financer leur retour."}, "club": {"quartier": "Chromeville", "ambiance": "Des basses qui font vibrer la cage thoracique, des stroboscopes qui découpent la foule. Lou mixe en hauteur, derrière une vitre fumée.", "hist": ["Le club Ondes occupe une ancienne centrale électrique. Les turbines sont toujours là, transformées en enceintes géantes.", "C'est le seul endroit de Chromeville où corpos et runners dansent côte à côte. Une trêve tacite : au club, on ne travaille pas.", "Le club ferme rarement avant l'aube. Les soirs de pluie acide, il ne ferme pas du tout : on dit que c'est pour abriter ceux qui n'ont nulle part où aller."], "secret": "Les playlists de Lou transportent des messages en morse pour les convois nomades. Le club est le plus gros relais de la résistance de la ville."}, "roofs": {"quartier": "Zone Zéro", "ambiance": "Une forêt d'antennes au-dessus du brouillard. Le vent siffle entre les câbles, la ville entière clignote sous tes pieds.", "hist": ["Les toits de la Zone Zéro sont reliés par des passerelles de fortune, posées par des générations de netrunners en quête de signal.", "C'est le territoire de Mira. Elle y a planté des relais pirates sur la moitié des antennes, et connaît chaque angle mort des drones.", "Les soirs clairs, on y voit la tour Kurogane d'un côté et les badlands de l'autre. Beaucoup de runners viennent juste pour ça : se rappeler qu'il existe un dehors."], "secret": "Sous une antenne rouillée, un ancien boîtier relais contient des milliers de messages d'effacés à leurs proches. Personne n'a jamais pu les délivrer."}, "laundry": {"quartier": "Bazar Néon", "ambiance": "Des rangées de machines qui tournent jour et nuit. Les néons verts clignotent, la radio crachote les infos.", "hist": ["La laverie 24/7 n'a jamais fermé, pas même pendant les grandes coupures. Son générateur de secours est le plus fiable du quartier.", "Okoro y « attend une lessive » depuis trois ans. C'est devenu son bureau : il y reçoit indics, témoins et parfois des flics qui ont des remords.", "Les habitués savent que la machine n°7 ne lave rien. On y dépose des messages, des puces, parfois de l'argent. Elle n'a jamais perdu un colis."], "secret": "Le sous-sol de la laverie abrite les archives d'Okoro : vingt-deux ans de dossiers de police, dont celui que Kurogane croit détruit."}, "arcade": {"quartier": "Chromeville", "ambiance": "Des bornes rétro qui clignotent dans la pénombre, l'odeur des chips au wasabi. Les high scores défilent sur un écran géant.", "hist": ["L'Arcade Pixel a été ouverte par un collectionneur obsédé par les jeux du XXᵉ siècle. Toutes les bornes sont d'origine, réparées pièce par pièce.", "C'est le royaume de Pixie, qui détient tous les records. Les autres joueurs viennent surtout pour tenter de la battre, sans succès.", "L'arcade sert aussi d'école clandestine : les gamins du quartier y apprennent à coder sur des bornes modifiées, loin des écoles corpo."], "secret": "Sous l'arcade, un serveur caché abrite une petite IA qui s'ennuyait. Pixie l'a adoptée : elle gère maintenant le classement des scores."}, "port": {"quartier": "Docks Noirs", "ambiance": "Des barges rouillées, des conteneurs empilés jusqu'au ciel, l'eau noire du canal qui clapote. Les grues grincent dans le brouillard.", "hist": ["Le port fluvial relie NEO-BXL aux canaux du nord. Officiellement, il transporte des matériaux de construction. Officieusement, tout le reste.", "Rook y gare son convoi quand il passe en ville. Les dockers le saluent comme un vieil ami, et ferment les yeux sur ses cargaisons.", "Le port ne dort jamais : les barges arrivent la nuit, quand les drones de Kurogane rentrent se recharger. C'est l'heure des vrais échanges."], "secret": "Le bassin 7 a été vidé et transformé en refuge : une centaine de nomades et d'effacés y vivent dans des conteneurs aménagés."}, "lab": {"quartier": "Bazar Néon", "ambiance": "Un ancien parking souterrain, des écrans qui clignotent entre les piliers. Ça sent l'alcool médical, une centrifugeuse ronronne dans un coin.", "hist": ["Quand Eliane Vex a fui Kurogane, elle a racheté ce parking abandonné pour une poignée d'eddies. Personne ne voulait de ce trou humide.", "Elle y a monté un laboratoire de bric et de broc, avec du matériel récupéré au marché et des machines « empruntées » à son ancien employeur.", "C'est ici que naît Mnémosyne, le protocole qui pourrait rendre leurs souvenirs aux effacés. Chaque niveau du parking est une étape du projet."], "secret": "Au dernier sous-sol, une chambre froide conserve des échantillons de Léthé. Vex la garde fermée à double tour : si Kurogane la trouvait, tout serait perdu."}, "bunker": {"quartier": "Zone Zéro", "ambiance": "Une porte blindée, un escalier en colimaçon, puis la salle : les meilleurs runners de la ville, une lumière rouge et un silence respectueux.", "hist": ["Le Bunker Zéro est un ancien abri antiaérien, creusé sous la gare il y a plus d'un siècle. Il a survécu à tout, y compris à l'oubli.", "Seules les légendes des quartiers y entrent. On y trouve les contrats les plus dangereux et les mieux payés de NEO-BXL.", "Les murs sont couverts de noms gravés : ceux des runners qui ne sont jamais revenus. On y boit en silence, une fois par an, pour eux."], "secret": "Un des noms gravés sur le mur est le tien. Quelqu'un l'a écrit avant ton effacement. Personne ne veut dire qui."}}};
